.container {
    width: 1220px;
    margin: auto;
}
.top-header {
    background: var(--color);
    color: #fff;
}
.top-menu li {

margin-right: 20px;

margin-top: 18px;
}
.top-menu li i {
    color: var(--yellow);
    margin: 0 5px;
    font-weight: 500;
    font-size: 15px;
}


.bars {
    width: 60px;
    height: 50px;
    background: var(--yellow);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
    margin-left: 70px;
}

.search-icon {
    margin-left: 20px;
    font-size: 23px;
