    z-index: 9;
	background: #fff;
}

.main-menu.flex-end {
    flex-direction: row;
    align-items: center;
}
.main-menu >  li {
    font-size: 19px;
    position:relative;
    padding: 20px;
}
.main-menu > li:after {
    content:'';
    position:absolute;
    width:0;
    height: 2px;
    bottom: 0;
    left:0;
    transition:.35s ease;
    background: var(--yellow);
}
.main-menu li:hover >a {
    color: var(--yellow);
}
.main-menu > li:hover:after {
    width:100%
}



.video-content:before {
    content: '';
    position: absolute;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    right: 20px;
    bottom: 40px;
    background: red;
    opacity: .2;
}
.video-content:after {
    content: '';
    position: absolute;
    width: 80px;
    right: -8px;
    height: 2px;
    bottom: 29px;
    background: red;
    opacity: .2;
    transform: rotate(-44deg);
}

.image-video i:after {
    content: " ";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    -webkit-box-shadow: 0 0 0 0 #f24080;
    box-shadow: 0 0 0 0 #f24080;
    -webkit-animation: button-ripple 3s infinite;
    animation: button-ripple 3s infinite;
    opacity: .6;

}


@keyframes button-ripple {
    70% {
        -webkit-box-shadow: 0 0 0 15px #f24080;
        box-shadow: 0 0 0 15px #f24080;
        opacity: 0
    }

    100% {
        -webkit-box-shadow: 0 0 0 0 #f24080;
        box-shadow: 0 0 0 0 #f24080;
        opacity: 0
    }
}


.video-container {
    position: fixed;
    width: 100%;
    height: 100%;
    top: 0;
    right: 0;
    bottom: 0;
    background: #000000b8;
    padding: 60px;
    z-index: 9999;
    visibility: hidden;
    opacity: 0;
    transition: .35s ease;
}
.video-container.open {
    visibility:visible;
    opacity:1
}

.close-video {
    position: absolute;
    width: 40px;
    height: 40px;
    color: #fff;
    border: 1px solid;
    border-radius: 50%;
    right: 20px;
    top: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
}



.overlay {
    position: fixed;
    width: 100%;
    height: 100%;
    top: 0;
    right: 0;
    background: #00000091;
    z-index: 9;
    visibility: hidden;
    opacity: 0;
    transition: .54s ease;
}
.overlay.open {
    visibility:visible;
    opacity:1
}


